"""Private dispatch embedded into the standalone installer; never imported by Web."""
import sys
import json
import os
import stat
import subprocess
import time
import uuid
import re
import math
from pathlib import Path



RUNTIME_STORAGE = Path('/var/lib/vantaline-release')


def trusted_directory(path, *, private=False):
    info = path.lstat()
    if (not stat.S_ISDIR(info.st_mode) or info.st_uid != os.geteuid()
            or stat.S_IMODE(info.st_mode) & 0o022
            or (private and stat.S_IMODE(info.st_mode) != 0o700)):
        raise ContractError('Untrusted runtime recovery directory')


def runtime_storage(*, create=False):
    # Every ancestor is root-owned and not writable by the application account.
    # Existing paths are checked, never chowned/chmodded or silently replaced.
    if os.geteuid() != 0:
        raise ContractError('Runtime recovery storage requires root')
    for ancestor in reversed(RUNTIME_STORAGE.parents):
        trusted_directory(ancestor)
    if create:
        try:
            RUNTIME_STORAGE.mkdir(mode=0o700)
            sync_directory(RUNTIME_STORAGE.parent)
        except FileExistsError:
            pass
    trusted_directory(RUNTIME_STORAGE, private=True)


def trusted_observation_tree(root, *, links):
    """Check imported code without following application-owned runtime links."""
    trusted_directory(root)
    def fail(error):
        raise error
    for directory, children, files in os.walk(root, followlinks=False, onerror=fail):
        for name in children + files:
            path = Path(directory) / name
            info = path.lstat()
            if stat.S_ISLNK(info.st_mode):
                if path in links and os.readlink(path) == str(links[path]):
                    continue
                resolved = path.resolve(strict=True)
                if not resolved.is_relative_to(root):
                    raise ContractError('Untrusted observation code link')
                continue  # Its destination is checked by the same tree walk.
            if (info.st_uid != 0 or stat.S_IMODE(info.st_mode) & 0o022
                    or not (stat.S_ISREG(info.st_mode) or stat.S_ISDIR(info.st_mode))):
                raise ContractError('Untrusted observation code')


def observe_runtime(release, commit):
    """Fixed read-only post-acceptance entry; never touches release state."""
    if (os.geteuid() != 0 or not re.fullmatch(r'v[0-9]{4}\.[0-9]{2}\.[0-9]+', release)
            or not re.fullmatch(r'[0-9a-f]{40}', commit)):
        raise ContractError('Invalid runtime observation request')
    base = Path('/opt/vantaline')
    target = base / 'releases' / release
    current = base / 'current'
    if (not current.is_symlink() or current.lstat().st_uid != 0
            or current.resolve(strict=True) != target):
        raise ContractError('Runtime observation release mismatch')
    trusted_directory(target)
    identity = RuntimeTransition.identity(target)
    if identity['topology']['commit'] != commit or not identity['topology']['runtime_protocol']:
        raise ContractError('Runtime observation identity mismatch')
    executable = Path('/usr/bin/python3')
    interpreter = executable.resolve(strict=True)
    for path in reversed(interpreter.parents):
        trusted_directory(path)
    info = interpreter.lstat()
    if not stat.S_ISREG(info.st_mode) or info.st_uid != 0 or stat.S_IMODE(info.st_mode) & 0o022:
        raise ContractError('Untrusted observation interpreter')
    # Existing service-owned ancestors are only metadata/data sources. Privileged
    # imports use an authenticated copy under independently trusted root storage.
    runtime_storage()
    trusted_directory(target / 'release/observer_bundle')
    # -I -S ignores Python environment, user site, .pth and sitecustomize.
    # Only the hash-locked immutable bundle and release are added. Service venv code is never imported.
    code = ("import sys,runpy,pathlib; root=sys.argv.pop(1); "
            "bundle=pathlib.Path(root)/'release/observer_bundle'; "
            "sys.path[:0]=[str(bundle),root]; import psycopg,psycopg_binary,typing_extensions; "
            "assert pathlib.Path(psycopg.__file__).resolve()==bundle/'psycopg/__init__.py'; "
            "assert pathlib.Path(psycopg_binary.__file__).resolve()==bundle/'psycopg_binary/__init__.py'; "
            "assert pathlib.Path(typing_extensions.__file__).resolve()==bundle/'typing_extensions.py'; "
            "assert psycopg.pq.__impl__ == 'binary'; "
            "runpy.run_module('local_inspection_service.runtime.observe_label_runtime',run_name='__main__')")
    with observer_snapshot(target, RUNTIME_STORAGE, OBSERVER_EXECUTION_FILES) as snapshot:
        trusted_observation_tree(snapshot, links={})
        bundle = snapshot / 'release/observer_bundle'
        try:
            verify_observer_bundle(bundle, snapshot / 'release/observer-dependencies.json')
        except (ObserverBundleError, OSError, ValueError, KeyError, TypeError):
            raise ContractError('Untrusted observation dependency bundle') from None
        result = subprocess.run([str(executable), '-I', '-S', '-B', '-c', code, str(snapshot),
                                 '--release', release, '--commit', commit, '--active-root', str(target)], cwd=snapshot,
                                env={'PATH': '/usr/bin:/bin', 'LANG': 'C.UTF-8', 'PSYCOPG_IMPL': 'binary'},
                                capture_output=True, text=True, timeout=45, check=True)
    if (not current.is_symlink() or current.lstat().st_uid != 0
            or current.resolve(strict=True) != target or RuntimeTransition.identity(target) != identity):
        raise ContractError('Runtime observation generation changed')
    if len(result.stdout) > 65536:
        raise ContractError('Invalid runtime observation response')
    value = json.loads(result.stdout)
    keys = {'schema', 'git_commit', 'release', 'worker_mode', 'config_revision',
            'maintenance', 'paused', 'queued_runs', 'active_runs', 'roles',
            'samples_before', 'periodic_progress'}
    if (not isinstance(value, dict) or set(value) != keys or type(value['schema']) is not int
            or value['schema'] != 1 or value['git_commit'] != commit or value['release'] != release
            or value['worker_mode'] != identity['topology']['mode']
            or not isinstance(value['config_revision'], str)
            or not re.fullmatch(r'[0-9a-f]{64}', value['config_revision'])
            or any(type(value[key]) is not bool for key in ('maintenance', 'paused'))
            or any(type(value[key]) is not int or value[key] < 0 for key in ('queued_runs', 'active_runs'))
            or value['active_runs'] > 2 or value['periodic_progress'] is not True):
        raise ContractError('Invalid runtime observation response')
    expected_roles = {'web', 'label'} if value['worker_mode'] == 'external' else {'web'}
    samples = []
    for key in ('samples_before', 'roles'):
        rows = value[key]
        if not isinstance(rows, list) or len(rows) != len(expected_roles):
            raise ContractError('Invalid runtime observation roles')
        indexed = {}
        for row in rows:
            if (not isinstance(row, dict) or set(row) != {'role', 'instance', 'pid', 'sampled_at'}
                    or row['role'] not in expected_roles or row['role'] in indexed
                    or not isinstance(row['instance'], str) or not re.fullmatch(r'[0-9a-f]{32}', row['instance'])
                    or type(row['pid']) is not int or row['pid'] <= 0
                    or type(row['sampled_at']) not in (int, float) or not math.isfinite(row['sampled_at'])
                    or row['sampled_at'] <= 0):
                raise ContractError('Invalid runtime observation roles')
            indexed[row['role']] = row
        samples.append(indexed)
    for role in expected_roles:
        before, after = samples[0][role], samples[1][role]
        if (before['instance'] != after['instance'] or before['pid'] != after['pid']
                or before['sampled_at'] >= after['sampled_at']):
            raise ContractError('Runtime observation did not advance')
    print(json.dumps(value, sort_keys=True))


def main():
    arguments = sys.argv[1:]
    operation = arguments.pop(0)
    if operation == 'observe' and len(arguments) == 2:
        try:
            observe_runtime(*arguments)
        except (RuntimeError, UnicodeError, OverflowError):
            raise ContractError('Runtime database observation failed') from None
        return
    if operation == 'prepare_storage' and not arguments:
        runtime_storage(create=True)
        return
    if operation == 'capabilities' and not arguments:
        print(json.dumps({'schema': 1, 'topologies': [1, 2], 'runtime_protocol': 1,
                          'services': [WEB, LABEL], 'drain_budget_seconds': 500, 'recovery_storage_schema': 1, 'configuration_schema': 1}, sort_keys=True))
        return
    if operation == 'validate' and len(arguments) == 3:
        directory, commit, allow_legacy = Path(arguments[0]), arguments[1], arguments[2] == '1'
        path = directory/'RUNTIME_TOPOLOGY.json'
        if not path.exists() and allow_legacy:
            print('runtime_topology=legacy-embedded')
            return
        topology = Topology.parse(read_object(path), commit)
        print('runtime_topology='+topology.mode)
        return
    if operation == 'mode' and len(arguments) == 2:
        identities = [RuntimeTransition.identity(Path(item)) for item in arguments]
        print('managed' if any(item['topology']['runtime_protocol'] for item in identities) else 'legacy')
        return
    if operation not in ('begin', 'start', 'accept', 'rollback', 'finish', 'verify', 'recover', 'previous', 'recovery_mode', 'prepare_recovery', 'check_journal') or len(arguments) < 1:
        raise ContractError('Unsupported controller operation')
    journal = Path(arguments.pop(0))
    if not journal.name.startswith('.runtime-transition-') or journal.parent != RUNTIME_STORAGE:
        raise ContractError('Invalid transition journal location')
    runtime_storage()
    if os.path.lexists(journal):
        info = journal.lstat()
        if not stat.S_ISREG(info.st_mode) or info.st_uid != os.geteuid() or stat.S_IMODE(info.st_mode) != 0o600:
            raise ContractError('Untrusted transition journal')
    if operation == 'check_journal' and not arguments:
        if os.path.lexists(journal):
            read_object(journal, limit=65536)
        return
    if operation == 'finish' and not arguments:
        journal.unlink(missing_ok=True)
        return
    if operation == 'rollback' and not os.path.lexists(journal):
        return  # Preparation failed before any mutable action.
    if operation == 'verify' and len(arguments) == 1:
        identity = RuntimeTransition.identity(Path(arguments[0]))
        if not identity['topology']['runtime_protocol']:
            return
    controller = RuntimeTransition(journal)
    if operation == 'previous' and not arguments:
        controller.load()
        print(controller.data['old']['directory'])
        return
    if operation == 'begin' and len(arguments) == 2:
        controller.begin(*(Path(item) for item in arguments))
    elif operation == 'start' and not arguments:
        controller.start()
    elif operation == 'accept' and not arguments:
        controller.accept()
    elif operation == 'rollback' and not arguments:
        controller.rollback(Path('/opt/vantaline/current'))
    elif operation == 'recovery_mode' and len(arguments) == 2:
        print(controller.recovery_mode(Path(arguments[0]), arguments[1]))
    elif operation == 'prepare_recovery' and len(arguments) == 1:
        controller.prepare_recovery(Path(arguments[0]))
    elif operation == 'recover' and len(arguments) == 1:
        controller.recover(Path(arguments[0]))
    elif operation == 'verify' and len(arguments) == 1:
        if os.path.lexists(journal):
            raise ContractError('Pending transition requires explicit recovery')
        controller.data = {'revision': uuid.uuid4().hex}
        controller.ready(controller.identity(Path(arguments[0])), deadline=time.monotonic()+15)
    else:
        raise ContractError('Invalid controller arguments')


if __name__ == '__main__':
    try:
        main()
    except (ContractError, OSError, ValueError, KeyError, TypeError, subprocess.SubprocessError):
        # State, paths, unit output and configuration never enter deployment logs.
        print('Runtime transition failed; retained recovery evidence requires inspection', file=sys.stderr)
        raise SystemExit(1) from None
PY_VANTALINE_RUNTIME
}

if [[ "${1:-}" == --capabilities && $# -eq 1 ]]; then runtime_controller capabilities; exit 0; fi

usage() { echo "usage: $0 --archive /opt/vantaline/incoming/ID.tar.gz --archive-sha256 HEX --release ID --commit SHA --apply" >&2; exit 2; }
if [[ "${1:-}" == --observe-runtime ]]; then
  [[ $# -eq 5 && "$2" == --release && "$4" == --commit ]] || usage
  runtime_controller observe "$3" "$5"
  exit 0
fi
archive=""; archive_sha256=""; release=""; commit=""; apply=0
while [[ $# -gt 0 ]]; do
  case "$1" in
    --archive) archive="$2"; shift 2 ;;
    --archive-sha256) archive_sha256="$2"; shift 2 ;;
    --release) release="$2"; shift 2 ;;
    --commit) commit="$2"; shift 2 ;;
    --apply) apply=1; shift ;;
    *) usage ;;
  esac
done
[[ "$release" =~ ^v[0-9]{4}\.[0-9]{2}\.[0-9]+$ ]] || usage
[[ "$commit" =~ ^[0-9a-f]{40}$ && "$archive_sha256" =~ ^[0-9a-f]{64}$ ]] || usage
[[ "$archive" == "/opt/vantaline/incoming/$release.tar.gz" && -f "$archive" && "$apply" -eq 1 ]] || usage
available_kb="$(df -Pk /opt/vantaline | awk 'NR==2 {print $4}')"
[[ "$available_kb" =~ ^[0-9]+$ && "$available_kb" -ge 2097152 ]] || { echo "less than 2 GiB free on /opt/vantaline" >&2; exit 1; }

base=/opt/vantaline; releases="$base/releases"; target="$releases/$release"; current="$base/current"
staged_archive="$base/.staged-$release.tar.gz"
lock="$base/backups/.production-release.lock"
db_url='postgresql:///vantaline?host=/var/run/postgresql&user=vantaline'
previous=""; switched=0; lock_owned=0; service_stopped=0; target_created=0
deployment_committed=0
controller_started=0; rollback_failed=0
runtime_directory=/var/lib/vantaline-release
runtime_journal="$runtime_directory/.runtime-transition-$release.json"
shared_backgrounds=""; legacy_backgrounds=""
installer_path=/usr/local/sbin/vantaline-install-release
installer_tmp="/usr/local/sbin/.vantaline-install-release.$$"
validate_target_topology() {
  local allow_existing_legacy="$1"
  runtime_controller validate "$target" "$commit" "$allow_existing_legacy"
}
verify_application() {
  version_json="$(curl --max-time 5 --retry 45 --retry-delay 1 --retry-all-errors -fsS http://127.0.0.1:8765/api/version)"
  printf '%s' "$version_json" | python3 -c 'import json,sys; d=json.load(sys.stdin); assert d["consistent"] is True and d["git_commit"]==sys.argv[1] and d["release"]==sys.argv[2]' "$commit" "$release"
  index="$(curl --max-time 5 -fsS http://127.0.0.1:8765/)"
  while read -r asset; do curl --max-time 5 -fsS "http://127.0.0.1:8765$asset" >/dev/null; done < <(printf '%s' "$index" | grep -oE '/static/assets/[^" ]+\.(js|css)' | sort -u)
  pid="$(systemctl show vantaline -p MainPID --value)"
  service_journal="$(journalctl _PID="$pid" --no-pager)" || return 1
  if printf '%s' "$service_journal" | grep -E 'Traceback|ERROR|CRITICAL' >/dev/null; then
    echo 'candidate service journal failed the health gate' >&2; return 1
  fi
  if [[ -f "$target/scripts/configure_pdf_proxy.py" ]]; then
    python3 "$target/scripts/configure_pdf_proxy.py"
  elif [[ -f "$target/RUNTIME_TOPOLOGY.json" ]]; then
    return 1
  fi
  # Old immutable packages have no observer. New artifacts require both modules.
  # Run from the candidate package; success is still before accept/commit.
  if [[ -f "$target/local_inspection_service/runtime/observe_label_runtime.py" ]]; then
    (cd "$target" && exec "$target/.venv/bin/python" -m local_inspection_service.runtime.observe_label_runtime --commit "$commit" --release "$release")
  fi
}
promote_installer() {
  install -o root -g root -m 0755 "$target/scripts/install_release.sh" "$installer_tmp"
  cmp -s "$target/scripts/install_release.sh" "$installer_tmp"
  [[ "$(stat -c '%U:%G %a' "$installer_tmp")" == "root:root 755" ]]
  mv -Tf "$installer_tmp" "$installer_path"
  cmp -s "$target/scripts/install_release.sh" "$installer_path"
}
rollback() {
  set +e
  if [[ "$controller_started" -eq 1 ]]; then
    if ! runtime_controller rollback "$runtime_journal"; then
      rollback_failed=1
      echo 'rollback_failed=true; retain complete releases and transition evidence' >&2
      return 1
    fi
    if ! version_json="$(curl --max-time 5 --retry 45 --retry-delay 1 --retry-all-errors -fsS http://127.0.0.1:8765/api/version)"; then
      rollback_failed=1; return 1
    fi
    if ! printf '%s' "$version_json" | /usr/bin/python3 -I -S -c 'import json,sys; d=json.load(sys.stdin); p=json.load(open(sys.argv[1]+"/VERSION.json")); assert d["consistent"] is True and d["git_commit"]==p["git_commit"] and d["release"]==p["release"]' "$previous"; then
      rollback_failed=1; return 1
    fi
    runtime_controller finish "$runtime_journal"
    return
  fi
  if [[ "$switched" -eq 1 && -n "$previous" ]]; then
    ln -sfn "$previous" "$current.rollback"; mv -Tf "$current.rollback" "$current"
  fi
  if [[ "$service_stopped" -eq 1 && -n "$shared_backgrounds" && -n "$legacy_backgrounds" ]]; then
    # The previous release still uses <repo>/backgrounds.  Repair that path
    # before restarting it.  If a compatibility link cannot be created, move
    # the directory back so rollback remains self-contained.
    if [[ -d "$shared_backgrounds" && ! -L "$shared_backgrounds" && ! -e "$legacy_backgrounds" && ! -L "$legacy_backgrounds" ]]; then
      ln -s "$shared_backgrounds" "$legacy_backgrounds" || mv "$shared_backgrounds" "$legacy_backgrounds"
    fi
    if [[ ! -d "$legacy_backgrounds" ]]; then
      echo "rollback stopped: previous backgrounds path is not accessible" >&2
      return
    fi
  fi
  if [[ "$service_stopped" -eq 1 ]]; then systemctl restart vantaline; fi
}
cleanup() {
  status=$?
  if [[ $status -ne 0 && "$deployment_committed" -eq 0 ]]; then
    rollback
    if [[ "$rollback_failed" -eq 0 && "$target_created" -eq 1 && "$(readlink -f "$current" 2>/dev/null || true)" != "$target" ]]; then rm -rf --one-file-system "$target"; fi
  fi
  if [[ $status -ne 0 && "$deployment_committed" -eq 1 ]]; then echo "application_committed=true control_promotion=incomplete; retry the same release" >&2; fi
  if [[ "$lock_owned" -eq 1 ]]; then rm -f "$lock"; fi
  if [[ "$lock_owned" -eq 1 ]]; then rm -f "$staged_archive"; fi
  rm -f "$installer_tmp"
  exit $status
}
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM

# Keep an advisory guard open across recovery of a dead PID lock. A live or
# ambiguous prior owner always blocks; a killed installer can be retried safely.
guard="$base/backups/.installation.guard"
[[ ! -L "$guard" ]]
(umask 077; touch "$guard")
[[ "$(stat -c '%u %a' "$guard")" == '0 600' ]]
exec 9>>"$guard"
/usr/bin/flock -n 9
/usr/bin/python3 -I -S - "$lock" <<'PY_RELEASE_LOCK'
import os, pathlib, stat, sys
path = pathlib.Path(sys.argv[1])
try:
    info = path.lstat()
except FileNotFoundError:
    raise SystemExit(0)
if not stat.S_ISREG(info.st_mode) or info.st_uid != 0 or info.st_mode & 0o022 or info.st_size > 32:
    raise SystemExit('Release lock requires inspection')
value = path.read_text().strip()
if not value.isdecimal() or int(value) <= 0:
    raise SystemExit('Release lock requires inspection')
try:
    os.kill(int(value), 0)
except ProcessLookupError:
    path.unlink()
else:
    raise SystemExit('Another release owner is still alive')
PY_RELEASE_LOCK
sh -c "set -o noclobber; printf '%s\n' '$$' > '$lock'"; lock_owned=1
# Keep the existing release guard protocol for old/new installer coordination.
# Old journals are never migrated, ignored or deleted by the storage bridge.
for pending in "$base"/backups/.runtime-transition-*.json; do
  [[ ! -e "$pending" && ! -L "$pending" ]] || { echo 'Legacy runtime transition requires inspection' >&2; exit 1; }
done
runtime_controller prepare_storage
runtime_controller check_journal "$runtime_journal"
for pending in "$runtime_directory"/.runtime-transition-*.json; do
  [[ ( ! -e "$pending" && ! -L "$pending" ) || "$pending" == "$runtime_journal" ]] || { echo 'Unfinished runtime transition must be recovered first' >&2; exit 1; }
done
[[ "$(stat -c '%U:%G' "$archive")" == "vantaline-deploy:vantaline-deploy" ]]
echo "$archive_sha256  $archive" | sha256sum -c -
if [[ -f "$runtime_journal" ]]; then
  recovery_mode="$(runtime_controller recovery_mode "$runtime_journal" "$target" "$commit")"
  previous="$(runtime_controller previous "$runtime_journal")"
  controller_started=1; target_created=1
  if [[ "$recovery_mode" == rollback ]]; then
    rollback || exit 1
    set -e
    [[ "$(readlink -f "$current")" != "$target" ]]
    rm -rf --one-file-system "$target"
    controller_started=0; target_created=0; previous=""
  else
    (cd "$target" && sha256sum -c SHA256SUMS)
    validate_target_topology 0
    runtime_controller prepare_recovery "$runtime_journal" "$target"
  fi
fi
systemctl is-active --quiet vantaline
[[ "$(systemctl show vantaline -p WorkingDirectory --value)" == "$current" ]]
if [[ -d "$target" ]]; then
  python3 - "$target/VERSION.json" "$release" "$commit" <<'PY'
import json, sys
doc=json.load(open(sys.argv[1],encoding="utf-8"))
assert doc["release"]==sys.argv[2] and doc["git_commit"]==sys.argv[3]
PY
  [[ "$(readlink -f "$current")" == "$target" ]] || { echo "release target exists but is not current" >&2; exit 1; }
  (cd "$target" && sha256sum -c SHA256SUMS)
  validate_target_topology 1
  verify_application
  if [[ -f "$runtime_journal" ]]; then
    previous="$(runtime_controller previous "$runtime_journal")"
    controller_started=1; target_created=1
    runtime_controller recover "$runtime_journal" "$target"
  else
    runtime_controller verify "$runtime_journal" "$target"
  fi
  deployment_committed=1
  if [[ "$controller_started" -eq 1 ]]; then runtime_controller finish "$runtime_journal"; fi
  if [[ -f "$target/RUNTIME_TOPOLOGY.json" ]]; then promote_installer; fi
  rm -f "$archive"
  echo "release=$release already-installed=true"
  exit 0
fi
preflight="$(sudo -u vantaline psql "$db_url" -tAc "select (select count(*) from vantaline.plc_workstation_leases where state in ('connecting','active','draining') and expires_at >= extract(epoch from clock_timestamp())::bigint)||'|'||(select count(*) from vantaline.plc_web_serial_dispatches where status = 'browser_attempt_declared');")"
[[ "$preflight" == "0|0" ]] || { echo "PLC activity preflight failed: $preflight" >&2; exit 1; }

install -d -o vantaline -g vantaline -m 755 "$target"
target_created=1
install -o vantaline -g vantaline -m 0400 "$archive" "$staged_archive"
sudo -u vantaline python3 - "$staged_archive" "$target" <<'PY'
import pathlib, sys, tarfile
archive, target = pathlib.Path(sys.argv[1]), pathlib.Path(sys.argv[2]).resolve()
with tarfile.open(archive, "r:gz") as handle:
    members = handle.getmembers()
    roots = {pathlib.PurePosixPath(m.name).parts[0] for m in members if pathlib.PurePosixPath(m.name).parts}
    if len(roots) != 1: raise SystemExit("release archive must contain exactly one root")
    root = next(iter(roots))
    for member in members:
        parts = pathlib.PurePosixPath(member.name).parts
        if not parts or parts[0] != root or member.issym() or member.islnk() or member.isdev() or member.isfifo():
            raise SystemExit(f"unsafe archive member: {member.name}")
        relative = pathlib.Path(*parts[1:]); destination = (target / relative).resolve()
        if destination != target and target not in destination.parents: raise SystemExit(f"archive traversal: {member.name}")
        member.name = relative.as_posix(); handle.extract(member, target)
PY
rm -f "$staged_archive"
(cd "$target" && sha256sum -c SHA256SUMS)
validate_target_topology 0
python3 - "$target/VERSION.json" "$release" "$commit" <<'PY'
import json, sys
doc=json.load(open(sys.argv[1],encoding="utf-8"))
assert doc["release"]==sys.argv[2] and doc["git_commit"]==sys.argv[3]
assert doc["backend_protocol"]==doc["frontend_protocol"]=="plc-web-serial-v4"
PY
sudo -u vantaline /opt/vantaline/venv/bin/python "$target/scripts/verify_production_dependencies.py" "$target/requirements-production.lock"
rm -rf "$target/local_inspection_service/data" "$target/models"
ln -s /opt/vantaline/shared/data "$target/local_inspection_service/data"
ln -s /opt/vantaline/shared/models "$target/models"
ln -s /opt/vantaline/venv "$target/.venv"

previous="$(readlink -f "$current")"
runtime_mode="$(runtime_controller mode "$previous" "$target")"
service_stopped=1
if [[ "$runtime_mode" == managed ]]; then
  controller_started=1
  runtime_controller begin "$runtime_journal" "$previous" "$target"
else
  systemctl stop vantaline
fi

# Background sets used to live at <repo>/backgrounds.  They are mutable runtime
# data and must live under the shared data tree before an immutable release is
# started.  The move is same-filesystem and happens while the service is stopped.
shared_backgrounds="$base/shared/data/backgrounds"
legacy_backgrounds="$previous/backgrounds"
if [[ -d "$shared_backgrounds" && ! -L "$shared_backgrounds" ]]; then
  if [[ -d "$legacy_backgrounds" && ! -L "$legacy_backgrounds" ]]; then
    echo "background directory conflict: both shared and legacy directories exist" >&2
    exit 1
  fi
elif [[ -e "$shared_backgrounds" || -L "$shared_backgrounds" ]]; then
  echo "shared backgrounds must be a real directory" >&2
  exit 1
else
  if [[ -d "$legacy_backgrounds" && ! -L "$legacy_backgrounds" ]]; then
    mv "$legacy_backgrounds" "$shared_backgrounds"
  elif [[ -e "$legacy_backgrounds" || -L "$legacy_backgrounds" ]]; then
    echo "legacy backgrounds has an unexpected type" >&2
    exit 1
  else
    install -d -o vantaline -g vantaline -m 755 "$shared_backgrounds"
  fi
fi
[[ -d "$shared_backgrounds" && ! -L "$shared_backgrounds" ]]
chown vantaline:vantaline "$shared_backgrounds"
sudo -u vantaline test -w "$shared_backgrounds"
# Keep the immediately previous version rollback-safe: its old code still
# resolves <repo>/backgrounds until the new release has passed health checks.
if [[ ! -e "$legacy_backgrounds" ]]; then
  ln -s "$shared_backgrounds" "$legacy_backgrounds"
fi
[[ -L "$legacy_backgrounds" && "$(readlink -f "$legacy_backgrounds")" == "$shared_backgrounds" ]]
for _ in $(seq 1 25); do
  active="$(sudo -u vantaline psql "$db_url" -tAc "select count(*) from vantaline.plc_workstation_leases where state in ('connecting','active','draining') and expires_at >= extract(epoch from clock_timestamp())::bigint;")"
  [[ "$active" == "0" ]] && break; sleep 1
done
final_gate="$(sudo -u vantaline psql "$db_url" -tAc "select (select count(*) from vantaline.plc_workstation_leases where state in ('connecting','active','draining') and expires_at >= extract(epoch from clock_timestamp())::bigint)||'|'||(select count(*) from vantaline.plc_web_serial_dispatches where status = 'browser_attempt_declared');")"
[[ "$final_gate" == "0|0" ]] || { echo "PLC fenced gate failed: $final_gate" >&2; exit 1; }

backup="$base/backups/db-schema-$release.sql"
sudo -u vantaline pg_dump -d vantaline --schema-only --schema=vantaline > "$backup"; chmod 600 "$backup"
sudo -u vantaline psql "$db_url" -v ON_ERROR_STOP=1 -c "CREATE TABLE IF NOT EXISTS vantaline.release_migration_checksums (version TEXT PRIMARY KEY, sha256 TEXT NOT NULL, applied_at BIGINT NOT NULL);"
for migration in "$target"/local_inspection_service/storage/migrations/*.sql; do
  [[ -e "$migration" ]] || continue
  version="$(basename "$migration" .sql)"; migration_sha="$(sha256sum "$migration" | awk '{print $1}')"
  [[ "$version" =~ ^[A-Za-z0-9._-]+$ ]] || { echo "invalid migration filename" >&2; exit 1; }
  stored="$(sudo -u vantaline psql "$db_url" -tAc "select sha256 from vantaline.release_migration_checksums where version = '$version';")"
  [[ -z "$stored" || "$stored" == "$migration_sha" ]] || { echo "migration checksum changed: $version" >&2; exit 1; }
  if [[ -z "$stored" ]]; then
    feature_applied="$(sudo -u vantaline psql "$db_url" -tAc "select count(*) from vantaline.feature_migrations where version = '$version';")"
    if [[ "$feature_applied" == "1" ]]; then
      sudo -u vantaline psql "$db_url" -v ON_ERROR_STOP=1 -c "BEGIN; SELECT pg_advisory_xact_lock(1448236621); INSERT INTO vantaline.release_migration_checksums(version,sha256,applied_at) VALUES ('$version','$migration_sha',extract(epoch from now())::bigint); COMMIT;"
      stored="$migration_sha"
    fi
  fi
  if [[ -z "$stored" ]]; then
    combined="$(mktemp)"
    python3 - "$migration" "$combined" "$version" "$migration_sha" <<'PY'
import pathlib, sys
source=pathlib.Path(sys.argv[1]).read_text(encoding="utf-8").strip()
lines=source.splitlines()
if lines[0].strip().upper() != "BEGIN;" or lines[-1].strip().upper() != "COMMIT;": raise SystemExit("migration transaction wrapper missing")
body="\n".join(lines[1:-1])
version=sys.argv[3].replace("'", "''"); digest=sys.argv[4]
pathlib.Path(sys.argv[2]).write_text("BEGIN;\nSELECT pg_advisory_xact_lock(1448236621);\n"+body+f"\nINSERT INTO vantaline.release_migration_checksums(version,sha256,applied_at) VALUES ('{version}','{digest}',extract(epoch from now())::bigint);\nCOMMIT;\n",encoding="utf-8")
PY
    chown vantaline:vantaline "$combined"; chmod 0400 "$combined"
    if ! sudo -u vantaline psql "$db_url" -v ON_ERROR_STOP=1 -f "$combined"; then rm -f "$combined"; exit 1; fi
    rm -f "$combined"
  fi
done

chown -R root:root "$target"; find "$target" -type d -exec chmod go-w {} +; find "$target" -type f -exec chmod go-w {} +
ln -sfn "$target" "$current.new"; mv -Tf "$current.new" "$current"; switched=1
if [[ "$controller_started" -eq 1 ]]; then runtime_controller start "$runtime_journal"; else systemctl start vantaline; fi
verify_application

# A single state transition commits the healthy application.  Before this
# assignment any signal performs a complete rollback; after it, cleanup must
# preserve the verified target and installer promotion can be rerun safely.
if [[ "$controller_started" -eq 1 ]]; then runtime_controller accept "$runtime_journal"; fi
deployment_committed=1
if [[ "$controller_started" -eq 1 ]]; then runtime_controller finish "$runtime_journal"; fi
rm -f "$archive"
promote_installer
echo "release=$release previous=$previous"
